import {widgetLifecycle} from './widget-class.js';
import {widgetDescendants} from './ui-assets.js';
const labels={initialized:'Initialized',preConstruct:'Pre Construct',construct:'Construct',destruct:'Destruct'};
export function renderWidgetClassFields(editor,data){
 const document=editor.document,inspector=editor.element.querySelector('.ui-properties'),selected=editor.doc.data.nodes.find(node=>node.id===editor.selected);
 inspector?.querySelector('[data-ui-class-fields]')?.remove();inspector?.querySelector('[data-ui-slot-exposure]')?.remove();editor.element.querySelector('[data-ui-inherited-tree]')?.remove();if(!inspector||!selected)return;
 if(selected.type==='NamedSlot'){
  const label=document.createElement('label'),input=document.createElement('input');label.dataset.uiSlotExposure='';label.textContent='인스턴스에서만 노출';input.type='checkbox';input.checked=!!selected.properties.exposeOnInstanceOnly;input.setAttribute('aria-label',label.textContent);input.onchange=event=>{event.stopPropagation();editor.edit(next=>next.nodes.find(node=>node.id===selected.id).properties.exposeOnInstanceOnly=input.checked);};label.append(input);inspector.querySelector('section')?.append(label);
 }
 const mount=data.nodes.find(node=>node.id===data.inheritedWidget),prefix=mount?.name+'/',hidden=new Set();if(mount)for(const node of data.nodes)if(node.name.startsWith(prefix)&&node.type==='NamedSlot'&&node.properties.exposeOnInstanceOnly)for(const id of widgetDescendants(data,node.id))hidden.add(id);const inherited=mount?data.nodes.filter(node=>node.name.startsWith(prefix)&&!hidden.has(node.id)):[];
 if(inherited.length){const tree=document.createElement('details');tree.dataset.uiInheritedTree='';tree.open=true;const title=document.createElement('summary');title.textContent='상속';tree.append(title);for(const node of inherited){if(node.type==='NamedSlot'&&node.properties.exposeOnInstanceOnly)continue;const button=document.createElement('button');button.className='ui-tree-node';button.textContent=node.name.slice(prefix.length);button.title=node.type;button.onclick=event=>{event.stopPropagation();editor.inheritedSelection=node.name.slice(prefix.length);editor.selected=editor.doc.data.nodes.find(node=>!node.parent).id;editor.render();};tree.append(button);}editor.element.querySelector('.ui-hierarchy')?.append(tree);}
 if(selected.parent)return;
 const section=document.createElement('section');section.dataset.uiClassFields='';
 const title=document.createElement('h3');title.textContent='위젯 클래스';section.append(title);
 const parentRow=document.createElement('label'),parent=document.createElement('select');parentRow.textContent='부모 위젯';parent.setAttribute('aria-label','부모 위젯');const files=[{path:'',name:'없음'},...editor.files().filter(file=>file.kind==='widget'&&file.path!==editor.doc.path)];if(editor.doc.data.parent&&!files.some(file=>file.path===editor.doc.data.parent))files.push({path:editor.doc.data.parent,name:editor.doc.data.parent});for(const file of files){const option=document.createElement('option');option.value=file.path;option.textContent=file.name;parent.append(option);}parent.value=editor.doc.data.parent||'';parent.onchange=event=>{event.stopPropagation();editor.inheritedSelection='';editor.edit(next=>{next.parent=parent.value;delete next.parentOverrides;delete next.parentSlots;});};parentRow.append(parent);section.append(parentRow);
 if(inherited.length){const row=document.createElement('label'),select=document.createElement('select');row.textContent='상속 요소';select.setAttribute('aria-label','상속 요소');for(const node of inherited){if(node.type==='NamedSlot'&&node.properties.exposeOnInstanceOnly)continue;const option=document.createElement('option');option.value=node.name.slice(prefix.length);option.textContent=option.value;select.append(option);}select.value=editor.inheritedSelection||select.options[0]?.value||'';const fields=document.createElement('div');section.append(row,fields);row.append(select);
  const show=()=>{editor.inheritedSelection=select.value;fields.replaceChildren();const node=inherited.find(node=>node.name===prefix+select.value);if(!node)return;for(const [key,label,type]of [['text','텍스트','text'],['visible','표시','checkbox'],['enabled','활성','checkbox'],['color','색상','color'],['value','값','number'],['opacity','불투명도','number']]){const line=document.createElement('label'),input=document.createElement('input');line.textContent=label;input.type=type;input.setAttribute('aria-label','상속 '+label);if(type==='checkbox')input.checked=node.properties[key];else input.value=node.properties[key];input.onchange=event=>{event.stopPropagation();const value=type==='checkbox'?input.checked:type==='number'?Number(input.value):input.value;editor.edit(next=>{next.parentOverrides??={};next.parentOverrides[select.value]={...next.parentOverrides[select.value],[key]:value};});};line.append(input);fields.append(line);}const reset=document.createElement('button');reset.textContent='기본값 복원';reset.onclick=event=>{event.stopPropagation();editor.edit(next=>{if(next.parentOverrides)delete next.parentOverrides[select.value];});};fields.append(reset);};select.onchange=event=>{event.stopPropagation();show();};show();
 }
 const events=document.createElement('details'),heading=document.createElement('summary');heading.textContent='생명주기 이벤트';events.append(heading);for(const phase of widgetLifecycle){const row=document.createElement('label'),input=document.createElement('input');row.textContent=labels[phase];input.value=editor.doc.data.lifecycle?.[phase]||'';input.placeholder='커스텀 이벤트';input.maxLength=80;input.setAttribute('aria-label','위젯 '+labels[phase]);input.onchange=event=>{event.stopPropagation();editor.edit(next=>{next.lifecycle??={};if(input.value)next.lifecycle[phase]=input.value;else delete next.lifecycle[phase];});};row.append(input);events.append(row);}section.append(events);
 const defaults=document.createElement('details'),summary=document.createElement('summary'),input=document.createElement('textarea');summary.textContent='초기 표시';input.value=JSON.stringify(editor.doc.data.preConstruct||{},null,2);input.setAttribute('aria-label','위젯 초기 표시');input.onchange=event=>{event.stopPropagation();try{const value=JSON.parse(input.value);editor.edit(next=>next.preConstruct=value);}catch(error){editor.hooks.error(error.message);}};defaults.append(summary,input);section.append(defaults);
 const identity=inspector.querySelector(':scope > section');inspector.insertBefore(section,identity?.nextSibling||null);
}
